import { Fragment } from "react";
import { phaseForNet } from "./nets";

/** Named aliases for the four direct CPU-to-display control connections.
 * Every other legacy remaining-route endpoint already has an electrical
 * connection in its owning TSX section. Copper is generated by the phases.
 */
const displayControlAliases = [
  { name: "REMAINING_114", net: "LCD_AC_BIAS_EN", from: "U1.R6", width: 0.1 },
  { name: "REMAINING_115", net: "LCD_HSYNC", from: "U1.R5", width: 0.1 },
  { name: "REMAINING_116", net: "LCD_PCLK", from: "U1.V5", width: 0.1 },
  { name: "REMAINING_251", net: "LCD_VSYNC", from: "U1.U5", width: 0.1 },
] as const;

export function RemainingRoutes() {
  return <>
    {displayControlAliases.map(({ name, net, from, width }) => (
      <Fragment key={name}>
        <trace
          name={name}
          from={from}
          to={`net.ROUTED_${net}`}
          thickness={width}
          routingPhaseIndex={phaseForNet(net)}
        />
      </Fragment>
    ))}
  </>;
}
